1	// PhishSense game logic (runs in the browser)
2	
3	const ROUNDS = 5;        // rounds per mode
4	const TO_PASS = 4;       // correct answers needed for the badge
5	const PER_CORRECT = 100; // points per correct answer
6	const BADGES = { easy: "🐟 Minnow", medium: "🎣 Angler", hard: "⚓ Captain" };
7	const ALL_MODES = ["easy", "medium", "hard"];
8	const MISSIONS = {
9	  easy: "Warm-up shift. These scams are obvious: watch for typos, surprise prizes, and ALL CAPS urgency.",
10	  medium: "Scammers are getting smarter. Check every sender address and phone number against the real ones above.",
11	  hard: "Expert level. Some scams look perfect, and some real emails look scary. Read every detail before you decide.",
12	};
13	
14	// The real addresses players check every message against.
15	const TRUSTED = [
16	  { name: "Bayline Energy", note: "your company", domain: "bayline-energy.com", phone: "(404) 555-0100" },
17	  { name: "NewsNow", domain: "newsnow.com" },
18	  { name: "ConnectPro", domain: "connectpro.com" },
19	  { name: "TechHub", domain: "techhub.com" },
20	];
21	
22	let mode, round, correct, current, seen;
23	let results;  // one entry per round: true (correct) or false (wrong)
24	let streak;   // correct answers in a row, resets on a wrong answer
25	let missed;   // every red flag from the rounds the player got wrong
26	
27	const $ = (id) => document.getElementById(id);
28	const show = (id) => {
29	  ["start-screen", "mission-screen", "play-screen", "end-screen"].forEach((s) => $(s).classList.add("hidden"));
30	  $(id).classList.remove("hidden");
31	};
32	const esc = (t) => String(t ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
33	
34	// Players who ask for less motion get the same game with the animations off.
35	const calmMode = () => window.matchMedia("(prefers-reduced-motion: reduce)").matches;
36	
37	// ---------- Talking to the backend ----------
38	// Practice mode: if the backend isn't running (opened as a file, Live Server,
39	// or a static host like Vercel), the game uses mock-data.js instead.
40	let OFFLINE = location.protocol === "file:";
41	
42	async function checkBackend() {
43	  if (OFFLINE) return;
44	  try {
45	    const r = await fetch("/api/leaderboard");
46	    if (!r.ok) throw new Error("no backend");
47	    await r.json();
48	  } catch (e) {
49	    OFFLINE = true;
50	  }
51	}
52	
53	async function apiGetScenario(mode, seen) {
54	  if (OFFLINE) {
55	    const pool = MOCK_SCENARIOS.filter((s) => s.difficulty === mode && !seen.includes(s.scenario_id));
56	    const s = pool[Math.floor(Math.random() * pool.length)];
57	    return { scenario_id: s.scenario_id, channel: s.channel, sender: s.sender, subject: s.subject, body: s.body, link: s.link };
58	  }
59	  return fetch(`/api/scenario?mode=${mode}&seen=${seen.join(",")}`).then((r) => r.json());
60	}
61	
62	async function apiAnswer(scenario_id, guess) {
63	  if (OFFLINE) {
64	    const s = MOCK_SCENARIOS.find((x) => x.scenario_id === scenario_id);
65	    return { correct: guess === s.game_answer, game_answer: s.game_answer, red_flags: s.red_flags, explanation: s.explanation };
66	  }
67	  return fetch("/api/answer", {
68	    method: "POST",
69	    headers: { "Content-Type": "application/json" },
70	    body: JSON.stringify({ scenario_id, guess }),
71	  }).then((r) => r.json());
72	}
73	
74	async function apiSaveScore(username, points, badge) {
75	  if (OFFLINE) {
76	    const board = JSON.parse(localStorage.getItem("ps-board") || "{}");
77	    const p = board[username] || { username, total_score: 0, badges: [] };
78	    p.total_score += points;
79	    if (badge && !p.badges.includes(badge)) p.badges.push(badge);
80	    board[username] = p;
81	    try { localStorage.setItem("ps-board", JSON.stringify(board)); } catch (e) {}
82	    return p;
83	  }
84	  return fetch("/api/score", {
85	    method: "POST",
86	    headers: { "Content-Type": "application/json" },
87	    body: JSON.stringify({ username, points, badge }),
88	  }).then((r) => r.json());
89	}
90	
91	async function apiLeaderboard() {
92	  if (OFFLINE) {
93	    let board = {};
94	    try { board = JSON.parse(localStorage.getItem("ps-board") || "{}"); } catch (e) {}
95	    return Object.values(board)
96	      .sort((a, b) => b.badges.length - a.badges.length || b.total_score - a.total_score)
97	      .slice(0, 10);
98	  }
99	  return fetch("/api/leaderboard").then((r) => r.json());
100	}
101	
102	// ---------- Trusted contacts ----------
103	// One list, shown on the mission briefing and in the panel during play.
104	function contactsHTML() {
105	  const rows = TRUSTED.map((c) => `<tr>
106	      <th scope="row">${esc(c.name)}${c.note ? `<small>${esc(c.note)}</small>` : ""}</th>
107	      <td><span class="contact-domain">${esc(c.domain)}</span>${c.phone ? `<span class="contact-phone">${esc(c.phone)}</span>` : ""}</td>
108	    </tr>`).join("");
109	  return `<table class="contacts-table">
110	      <thead><tr><th scope="col">Company</th><th scope="col">Real website &amp; phone</th></tr></thead>
111	      <tbody>${rows}</tbody>
112	    </table>
113	    <p class="contacts-tip">Scammers use names you trust with addresses that don't match. Always compare.</p>`;
114	}
115	document.querySelectorAll(".contacts-list").forEach((el) => (el.innerHTML = contactsHTML()));
116	
117	function setContactsOpen(open) {
118	  $("contacts-panel").classList.toggle("hidden", !open);
119	  $("btn-contacts").setAttribute("aria-expanded", String(open));
120	  $("btn-contacts").classList.toggle("open", open);
121	}
122	$("btn-contacts").addEventListener("click", () =>
123	  setContactsOpen($("contacts-panel").classList.contains("hidden")));
124	document.addEventListener("keydown", (e) => {
125	  if (e.key === "Escape" && !$("contacts-panel").classList.contains("hidden")) {
126	    setContactsOpen(false);
127	    $("btn-contacts").focus();
128	  }
129	});
130	
131	// ---------- Start: pick a difficulty, then see the mission ----------
132	document.querySelectorAll(".mode").forEach((btn) =>
133	  btn.addEventListener("click", () => {
134	    if (!$("username").value.trim()) return $("username").focus();
135	    mode = btn.dataset.mode;
136	    const label = mode.charAt(0).toUpperCase() + mode.slice(1);
137	    $("mission-mode").textContent = `${label} mode · ${BADGES[mode]} badge`;
138	    $("mission-tip").textContent = MISSIONS[mode];
139	    show("mission-screen");
140	  })
141	);
142	
143	$("btn-back").addEventListener("click", () => show("start-screen"));
144	
145	$("btn-start").addEventListener("click", () => {
146	  round = 0;
147	  correct = 0;
148	  seen = [];
149	  results = [];
150	  streak = 0;
151	  missed = [];
152	  $("recap").classList.add("hidden");
153	  $("badge-reveal").classList.add("hidden");
154	  $("confetti").innerHTML = "";
155	  setContactsOpen(false);
156	  show("play-screen");
157	  nextRound();
158	});
