160	// ---------- Progress dots + streak ----------
161	function renderDots() {
162	  let html = "";
163	  for (let i = 0; i < ROUNDS; i++) {
164	    let cls = "";
165	    if (results[i] === true) cls = "correct";
166	    else if (results[i] === false) cls = "wrong";
167	    else if (i === round - 1) cls = "current";
168	    html += `<span class="dot ${cls}"></span>`;
169	  }
170	  $("dots").innerHTML = html;
171	  $("dots").setAttribute("aria-label", `Round ${Math.min(round, ROUNDS)} of ${ROUNDS}, ${correct} correct`);
172	}
173	
174	function renderStreak() {
175	  $("streak").textContent =
176	    streak >= 2 ? `🔥 ${streak} in a row` : streak === 1 ? "🔥 1 correct" : "";
177	}
178	
179	// ---------- Play ----------
180	async function nextRound() {
181	  await ready;
182	  round++;
183	  $("progress").textContent = `${mode.toUpperCase()} · Round ${round} of ${ROUNDS} · ${correct} correct`;
184	  $("result").classList.add("hidden");
185	  $("btn-next").classList.add("hidden");
186	  $("btn-phish").disabled = $("btn-legit").disabled = true;
187	  $("message").className = "card";   // clears the glow or shake from the last round
188	  $("message").style.transformOrigin = "";
189	  $("pop-layer").innerHTML = "";
190	  $("reaction").className = "reaction hidden";
191	  $("reaction").textContent = "";
192	  hidePeek();
193	  renderDots();
194	  renderStreak();
195	  $("message").innerHTML = `<p class="loading">Loading message...</p>`;
196	
197	  current = await apiGetScenario(mode, seen);
198	  seen.push(current.scenario_id);
199	  $("message").innerHTML = renderMessage(current);
200	  $("btn-phish").disabled = $("btn-legit").disabled = false;
201	}
202	
203	// A steady clock time per scenario, so the inbox and phone look real
204	// without the time jumping around every time you re-read a message.
205	function clockFor(s) {
206	  const id = Math.abs(Number(s.scenario_id) || 0);
207	  const hour24 = 8 + ((id * 3) % 9);          // 8 AM to 4 PM
208	  const minute = String((id * 17) % 60).padStart(2, "0");
209	  const hour12 = hour24 % 12 === 0 ? 12 : hour24 % 12;
210	  return { short: `${hour12}:${minute}`, long: `${hour12}:${minute} ${hour24 < 12 ? "AM" : "PM"}` };
211	}
212	
213	const initialOf = (sender) => {
214	  const m = String(sender || "").match(/[a-z]/i);
215	  return m ? m[0].toUpperCase() : "?";
216	};
217	
218	// ---------- Hover to inspect links ----------
219	// Emails hide the real address behind friendly text, the way real phishing
220	// does. Hovering (or tapping) shows where the link really goes. The link is a
221	// plain button, so it can never open anything.
222	const LINK_LABELS = [
223	  [/\.exe|download|update/i, "Download the update"],
224	  [/claim|winner|prize|reward/i, "Claim your reward"],
225	  [/sign-?in|log-?in/i, "Sign in to your account"],
226	  [/verify/i, "Verify your account"],
227	  [/confirm/i, "Confirm now"],
228	  [/billing|invoice|payment/i, "View billing details"],
229	  [/video|watch/i, "Watch now"],
230	  [/story|news|article/i, "Read the full story"],
231	];
232	
233	function parseLink(raw) {
234	  const text = String(raw || "").trim();
235	  try {
236	    const u = new URL(/^[a-z]+:\/\//i.test(text) ? text : `http://${text}`);
237	    const host = u.hostname;
238	    const parts = host.split(".");
239	    const domain = parts.length > 2 ? parts.slice(-2).join(".") : host;
240	    return {
241	      scheme: `${u.protocol}//`,
242	      sub: host.slice(0, host.length - domain.length), // e.g. "newsnow.com."
243	      domain,                                          // the site you really land on
244	      rest: u.pathname === "/" && !u.search ? "" : u.pathname + u.search,
245	    };
246	  } catch (e) {
247	    return { scheme: "", sub: "", domain: text, rest: "" };
248	  }
249	}
250	
251	function linkLabel(s) {
252	  if (s.link_text) return s.link_text;
253	  const { rest } = parseLink(s.link);
254	  const hit = LINK_LABELS.find(([re]) => re.test(rest)) || LINK_LABELS.find(([re]) => re.test(s.link));
255	  return hit ? hit[1] : "Open link";
256	}
257	
258	function renderLink(s) {
259	  if (!s.link) return "";
260	  const hint = `<span class="link-hint"><span class="hint-hover">Hover</span><span class="hint-tap">Tap</span> to inspect</span>`;
261	  if (s.channel === "sms") {
262	    // Texts show the raw address, but tapping it still previews the real site.
263	    return `<p class="link"><button type="button" class="link-chip" data-href="${esc(s.link)}">${esc(s.link)}</button>${hint}</p>`;
264	  }
265	  return `<p class="link"><button type="button" class="link-chip" data-href="${esc(s.link)}">🔗 ${esc(linkLabel(s))}</button>${hint}</p>`;
266	}
267	
268	const peek = document.createElement("div");
269	peek.id = "link-peek";
270	peek.className = "link-peek";
271	peek.setAttribute("role", "tooltip");
272	peek.hidden = true;
273	document.body.appendChild(peek);
274	
275	let peekFor = null;     // the link the popup belongs to
276	let peekPinned = false; // true after a tap or click, so it stays open
277	
278	function showPeek(chip) {
279	  const p = parseLink(chip.dataset.href);
280	  peek.innerHTML = `
281	    <p class="peek-title">🔍 This link really goes to:</p>
282	    <p class="peek-url">${esc(p.scheme)}${p.sub ? `<span class="peek-sub">${esc(p.sub)}</span>` : ""}<b class="peek-domain">${esc(p.domain)}</b>${esc(p.rest)}</p>
283	    <p class="peek-tip">The real site is the last part of the address, right before the first /</p>`;
284	  peek.hidden = false;
285	  if (peekFor && peekFor !== chip) peekFor.removeAttribute("aria-describedby");
286	  peekFor = chip;
287	  chip.setAttribute("aria-describedby", "link-peek");
288	  placePeek();
289	}
290	
291	function hidePeek() {
292	  peek.hidden = true;
293	  peekPinned = false;
294	  if (peekFor) peekFor.removeAttribute("aria-describedby");
295	  peekFor = null;
296	}
297	
298	// Always open ABOVE the link, so it never covers the Phish / Legit buttons
299	// below the message. If the link is too close to the top of the screen,
300	// scroll up just enough to make room.
301	function placePeek() {
302	  if (!peekFor || peek.hidden) return;
303	  if (!document.body.contains(peekFor)) return hidePeek();
304	  const gap = 8, edge = 12;
305	  const w = peek.offsetWidth, h = peek.offsetHeight;
306	  let r = peekFor.getBoundingClientRect();
307	  const short = edge - (r.top - gap - h);
308	  if (short > 0 && window.scrollY > 0) {
309	    window.scrollBy(0, -Math.min(short, window.scrollY));
310	    r = peekFor.getBoundingClientRect();
311	  }
312	  const top = Math.max(edge, r.top - gap - h);
313	  const left = Math.min(Math.max(edge, r.left), window.innerWidth - w - edge);
314	  peek.style.top = `${top}px`;
315	  peek.style.left = `${Math.max(edge, left)}px`;
316	}
317	
318	const chipFrom = (e) => e.target.closest?.(".link-chip");
319	
320	document.addEventListener("mouseover", (e) => {
321	  const chip = chipFrom(e);
322	  if (chip && !peekPinned) showPeek(chip);
323	});
324	document.addEventListener("mouseout", (e) => {
325	  const chip = chipFrom(e);
326	  if (chip && !peekPinned && !chip.contains(e.relatedTarget)) hidePeek();
327	});
328	document.addEventListener("focusin", (e) => {
329	  const chip = chipFrom(e);
330	  if (chip) showPeek(chip);
331	});
332	document.addEventListener("focusout", (e) => {
333	  if (chipFrom(e) && !peekPinned) hidePeek();
334	});
335	document.addEventListener("click", (e) => {
336	  const chip = chipFrom(e);
337	  if (chip) {
338	    e.preventDefault();
339	    if (peekPinned && peekFor === chip) return hidePeek();
340	    showPeek(chip);
341	    peekPinned = true;
342	  } else if (peekPinned && !peek.contains(e.target)) {
343	    hidePeek();
344	  }
345	});
346	document.addEventListener("keydown", (e) => { if (e.key === "Escape") hidePeek(); });
347	window.addEventListener("scroll", placePeek, { passive: true });
348	window.addEventListener("resize", placePeek);
349	
350	function renderMessage(s) {
351	  const link = renderLink(s);
352	  const clock = clockFor(s);
353	
354	  if (s.channel === "sms") {
355	    return `<div class="sms">
356	      <div class="status-bar">
357	        <span class="sb-time">${esc(clock.short)}</span>
358	        <span class="sb-right">
359	          <span class="signal" aria-hidden="true"><i></i><i></i><i></i><i></i></span>
360	          <span class="battery" aria-hidden="true"><span class="bat-fill"></span></span>
361	        </span>
362	      </div>
363	      <p class="label">💬 Text message from <b>${esc(s.sender)}</b></p>
364	      <p class="bubble">${esc(s.body)}</p>${link}</div>`;
365	  }
366	
367	  return `<div class="email">
368	    <div class="email-head">
369	      <div class="avatar" aria-hidden="true">${esc(initialOf(s.sender))}</div>
370	      <div class="email-who">
371	        <p class="from"><b>From:</b> ${esc(s.sender)}</p>
372	        <p class="subject">${esc(s.subject || "(no subject)")}</p>
373	      </div>
374	      <p class="email-time">${esc(clock.long)}</p>
375	    </div>
376	    <p class="body">${esc(s.body)}</p>${link}
377	    <div class="email-actions">
378	      <button type="button" disabled>↩ Reply</button>
379	      <button type="button" disabled>↪ Forward</button>
380	    </div>
381	  </div>`;
382	}
383	
384	// Red flags arrive as one string with semicolons between them.
385	function flagList(red_flags) {
386	  const parts = Array.isArray(red_flags) ? red_flags : String(red_flags || "").split(";");
387	  return parts.map((f) => String(f).trim()).filter(Boolean);
388	}
389	
390	function floatScore(text) {
391	  if (calmMode()) return;
392	  const bit = document.createElement("span");
393	  bit.className = "pop-score";
394	  bit.textContent = text;
395	  $("pop-layer").appendChild(bit);
396	  setTimeout(() => bit.remove(), 1500);
397	}
398	
399	// ---------- Answer reactions: hooked, dodged, too cautious, safe ----------
400	const REACTIONS = {
401	  hooked:   "🎣 You got hooked!",
402	  dodged:   "✅ You dodged the hook!",
403	  cautious: "🤔 Too cautious! This one was safe.",
404	  safe:     "✅ Correct, this one's safe.",
405	};
406	
407	// Which of the 4 reactions fits: the real answer vs. the player's guess.
408	function reactionFor(r, guess) {
409	  const real = String(r.game_answer || "").toLowerCase();
410	  const said = guess.toLowerCase();
411	  if (real === "phish") return said === "phish" ? "dodged" : "hooked";
412	  if (real === "legit") return said === "legit" ? "safe" : "cautious";
413	  return r.correct ? "safe" : "hooked";
414	}
415	
416	function showReaction(kind) {
417	  const el = $("reaction");
418	  el.textContent = REACTIONS[kind];
419	  el.className = `reaction ${kind}`;
420	}
421	
422	// The hook and line, drawn as inline SVG (a dark outline under a light
423	// stroke, so it shows up over both the navy page and the white email).
424	const HOOK_SVG = `<svg class="hook" width="34" height="48" viewBox="0 0 34 48" aria-hidden="true">
425	  <g fill="none" stroke-linecap="round" stroke-linejoin="round">
426	    <g stroke="#0a1a33" stroke-width="5.5"><circle cx="20" cy="5" r="3.5"/><path d="M20 8.5V32a9 9 0 0 1-18 0v-8l5 5"/></g>
427	    <g stroke="#e9f1f7" stroke-width="3"><circle cx="20" cy="5" r="3.5"/><path d="M20 8.5V32a9 9 0 0 1-18 0v-8l5 5"/></g>
428	  </g>
429	</svg>`;
430	
431	// The rig hangs from the top of the visible screen. It lives in page
432	// coordinates, so it stays lined up with the card even if the page scrolls.
433	function makeRig(x, drop) {
434	  const rig = document.createElement("div");
435	  rig.className = "hook-rig";
436	  rig.setAttribute("aria-hidden", "true");
437	  rig.style.left = `${x + window.scrollX}px`;
438	  rig.style.top = `${window.scrollY}px`;
439	  rig.style.setProperty("--drop", `${drop}px`);
440	  rig.innerHTML = `<span class="hook-line"></span>${HOOK_SVG}`;
441	  document.body.appendChild(rig);
442	  return rig;
443	}
444	
445	const done = (anim) => anim.finished.catch(() => {});
446	
447	// Where the hook should aim: the top of the visible part of the message.
448	function cardTarget() {
449	  const card = $("message");
450	  const box = (card.firstElementChild || card).getBoundingClientRect();
451	  return { card, box, top: Math.max(box.top, 12), x: box.left + box.width / 2 };
452	}
453	
454	// Phish, player said Legit: the hook drops, bites, and yanks the card away.
455	async function playHooked() {
456	  const { card, box, top, x } = cardTarget();
457	  const drop = Math.max(top - 26, 4);   // hook's bend lands just inside the card's top edge
458	  const above = drop + 60;              // far enough up to start off screen
459	  const lift = box.bottom + 80;         // far enough up to leave the screen
460	  const rig = makeRig(x, drop);
461	  const pull = "cubic-bezier(0.55, 0, 0.8, 0.2)";
462	
463	  card.classList.add("hook-anim");
464	  card.style.transformOrigin = `50% ${top - card.getBoundingClientRect().top + 14}px`;
465	
466	  const opts = { duration: 1250, fill: "forwards" };
467	  const rigAnim = rig.animate([
468	    { transform: `translateY(${-above}px)`, easing: "cubic-bezier(0.3, 0.6, 0.4, 1)" },
469	    { transform: "translateY(0px)", offset: 0.34 },
470	    { transform: "translateY(7px)", offset: 0.42 },
471	    { transform: "translateY(0px)", offset: 0.5, easing: pull },
472	    { transform: `translateY(${-lift}px)` },
473	  ], opts);
474	  const cardAnim = card.animate([
475	    { transform: "translateY(0px) rotate(0deg)" },
476	    { transform: "translateY(0px) rotate(0deg)", offset: 0.34 },
477	    { transform: "translateY(7px) rotate(0deg)", offset: 0.42 },
478	    { transform: "translateY(0px) rotate(-2deg)", offset: 0.5, easing: pull },
479	    { transform: `translateY(${-lift}px) rotate(-4deg)` },
480	  ], opts);
481	
482	  await Promise.all([done(rigAnim), done(cardAnim)]);
483	  rig.remove();
484	
485	  // Bring the message back so the player can read it next to the explanation.
486	  const back = card.animate(
487	    [{ opacity: 0, transform: "translateY(-12px)" }, { opacity: 1, transform: "none" }],
488	    { duration: 280, easing: "ease-out" }
489	  );
490	  cardAnim.cancel();
491	  done(back).then(() => card.classList.remove("hook-anim"));
492	}
493	
494	// Phish, player said Phish: the hook swings down, the card ducks, the hook misses.
495	async function playDodged() {
496	  const { card, top, x } = cardTarget();
497	  const drop = Math.max(top - 36, 4);   // would just graze the card if it stayed put
498	  const above = drop + 60;
499	  const rig = makeRig(x, drop);
500	
501	  card.classList.add("hook-anim");
502	
503	  const opts = { duration: 1100 };
504	  const rigAnim = rig.animate([
