506	    { transform: "translateY(0px) rotate(0deg)", offset: 0.3 },
507	    { transform: "translateY(0px) rotate(4deg)", offset: 0.42 },
508	    { transform: "translateY(0px) rotate(-3deg)", offset: 0.54 },
509	    { transform: "translateY(0px) rotate(0deg)", offset: 0.64, easing: "ease-in" },
510	    { transform: `translateY(${-above}px) rotate(0deg)` },
511	  ], { ...opts, fill: "forwards" });
512	  const cardAnim = card.animate([
513	    { transform: "translateY(0px) scale(1)" },
514	    { transform: "translateY(0px) scale(1)", offset: 0.16 },
515	    { transform: "translateY(18px) scale(0.98)", offset: 0.3 },
516	    { transform: "translateY(18px) scale(0.98)", offset: 0.62 },
517	    { transform: "translateY(0px) scale(1)", offset: 0.82 },
518	    { transform: "translateY(0px) scale(1)" },
