528	async function answer(guess) {
529	  if (answering) return;   // ignore double clicks while a reaction plays
530	  answering = true;
531	  $("btn-phish").disabled = $("btn-legit").disabled = true;
532	  hidePeek();
533	
534	  try {
535	    const r = await apiAnswer(current.scenario_id, guess);
536	    const kind = reactionFor(r, guess);
537	
538	    results[round - 1] = !!r.correct;
539	    if (r.correct) {
540	      correct++;
541	      streak++;
542	    } else {
543	      streak = 0;
544	      flagList(r.red_flags).forEach((f) => missed.push(f));
545	    }
546	    renderDots();
547	    renderStreak();
548	    showReaction(kind);
549	
550	    // Hook animations (skipped when the player asks for less motion).
551	    const animate = !calmMode() && typeof $("message").animate === "function";
552	    if (animate && kind === "hooked") await playHooked();
553	    if (animate && kind === "dodged") await playDodged();
554	
555	    const msg = $("message");
556	    if (kind === "hooked") msg.classList.add("is-hooked");
557	    else if (kind === "cautious") msg.classList.add("is-cautious");
558	    else {
559	      msg.classList.add("is-correct");
560	      floatScore(`+${PER_CORRECT}`);
561	    }
562	
563	    const flags = r.red_flags
564	      ? `<p><b>Red flags:</b></p><ul>${flagList(r.red_flags).map((f) => `<li>${esc(f)}</li>`).join("")}</ul>`
565	      : "";
566	    const went = current.link
567	      ? `<p class="link-reveal">🔍 That link really went to <b>${esc(parseLink(current.link).domain)}</b></p>`
568	      : "";
569	    const nudge = kind === "cautious"
570	      ? `<p class="gentle-tip">Being careful is a good habit! Before you report a message, check the sender and link against your trusted contacts.</p>`
571	      : "";
572	    $("result").innerHTML = `
573	      <h3>This one was <b>${esc(r.game_answer)}</b>.</h3>
574	      ${flags}<p>${esc(r.explanation)}</p>${went}${nudge}`;
575	    $("result").className = `card ${kind === "hooked" ? "bad" : kind === "cautious" ? "gentle" : "good"}`;
576	    $("progress").textContent = `${mode.toUpperCase()} · Round ${round} of ${ROUNDS} · ${correct} correct`;
577	    $("btn-next").textContent = round < ROUNDS ? "Next" : "See results";
578	    $("btn-next").classList.remove("hidden");
579	  } finally {
580	    answering = false;
581	  }
582	}
