588	// ---------- Badge reveal ----------
589	const CONFETTI_COLORS = ["#2de0c4", "#3ddc84", "#ffd166", "#ff5d6c", "#8ecae6", "#ffffff"];
590	
591	// Replays a CSS animation that has already run once this session.
592	function replayAnimation(el) {
593	  el.style.animation = "none";
594	  void el.offsetWidth;
595	  el.style.animation = "";
596	}
597	
598	function burstConfetti() {
599	  const layer = $("confetti");
600	  layer.innerHTML = "";
601	  if (calmMode()) return;
602	  for (let i = 0; i < 30; i++) {
603	    const bit = document.createElement("span");
604	    bit.className = "confetti-bit";
605	    bit.style.left = `${Math.random() * 100}%`;
606	    bit.style.background = CONFETTI_COLORS[i % CONFETTI_COLORS.length];
607	    bit.style.setProperty("--dx", `${(Math.random() - 0.5) * 240}px`);
608	    bit.style.setProperty("--rot", `${Math.random() * 900 - 450}deg`);
609	    bit.style.animationDelay = `${Math.random() * 0.35}s`;
610	    bit.style.animationDuration = `${1.5 + Math.random()}s`;
611	    if (i % 3 === 0) bit.style.borderRadius = "50%";
612	    layer.appendChild(bit);
613	  }
614	  setTimeout(() => { layer.innerHTML = ""; }, 3200);
615	}
