617	function revealBadge(isMaster) {
618	  const [icon, ...name] = BADGES[mode].split(" ");
619	  $("badge-art").textContent = icon;
620	  $("badge-name").textContent = name.join(" ");
621	  $("badge-reveal").classList.remove("hidden");
622	  replayAnimation($("badge-art"));
623	  replayAnimation($("badge-name"));
624	
625	  if (isMaster) {
626	    $("badge-master").textContent = "🏆 PhishSense Master: all three badges earned!";
627	    $("badge-master").classList.remove("hidden");
628	    replayAnimation($("badge-master"));
629	  } else {
630	    $("badge-master").classList.add("hidden");
631	  }
632	  burstConfetti();
633	}
