635	// ---------- End of run ----------
636	function renderRecap() {
637	  // Group the same red flag together so repeats show as a count.
638	  const groups = new Map();
639	  missed.forEach((flag) => {
640	    const key = flag.toLowerCase().replace(/\s+/g, " ");
641	    const hit = groups.get(key);
642	    if (hit) hit.n++;
643	    else groups.set(key, { text: flag, n: 1 });
644	  });
645	  const items = [...groups.values()].sort((a, b) => b.n - a.n);
646	
647	  $("recap").innerHTML = `<h3>Red flags you missed this run</h3>` + (items.length
648	    ? `<ul>${items.map((g) => `<li>${esc(g.text)}${g.n > 1 ? ` <span class="count">×${g.n}</span>` : ""}</li>`).join("")}</ul>`
649	    : `<p class="clean">You caught every red flag!</p>`);
650	  $("recap").classList.remove("hidden");
651	}
652	
653	async function finish() {
654	  const passed = correct >= TO_PASS;
655	  const badge = passed ? mode : null;
656	  const player = await apiSaveScore($("username").value.trim(), correct * PER_CORRECT, badge);
657	
658	  const owned = Array.isArray(player?.badges) ? player.badges : (passed ? [mode] : []);
659	  const isMaster = ALL_MODES.every((m) => owned.includes(m));
660	
661	  $("end-title").textContent = passed ? `You earned ${BADGES[mode]}!` : `${correct} of ${ROUNDS} correct`;
662	  $("end-text").textContent = passed
663	    ? "Nice catch. Try the next mode!"
664	    : `You need ${TO_PASS} to earn ${BADGES[mode]}. Every round is new, so try again!`;
665	
666	  if (passed) revealBadge(isMaster);
667	  else $("badge-reveal").classList.add("hidden");
668	
669	  renderRecap();
670	  show("end-screen");
671	  loadLeaderboard();
672	}
