676	// ---------- Leaderboard ----------
677	async function loadLeaderboard() {
678	  const rows = await apiLeaderboard();
679	  $("leaderboard").innerHTML = rows.length
680	    ? rows.map((p) => {
681	        const icons = p.badges.map((b) => BADGES[b]?.split(" ")[0] || "").join(" ");
682	        const master = ALL_MODES.every((b) => p.badges.includes(b)) ? " 🏆" : "";
683	        return `<li><b>${esc(p.username)}</b> ${icons}${master} <span>${p.total_score} pts</span></li>`;
684	      }).join("")
685	    : '<li class="empty">No scores yet. Be the first!</li>';
686	}
687	
688	const ready = checkBackend();
689	ready.then(loadLeaderboard);
