1	// Fish cursor: on the home screen, the mouse pointer becomes a little fish
2	// that turns to face where it's swimming, wags its tail, and blows bubbles.
3	// Only runs with a real mouse (not touch) and stays off for reduced motion.
4	(() => {
5	  const fine = window.matchMedia("(pointer: fine)").matches;
6	  const calm = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
7	  if (!fine || calm) return;
8	
9	  const home = document.getElementById("start-screen");
10	
11	  // Fish faces right; its nose (the click point) is at (46, 18).
12	  const fish = document.createElement("div");
13	  fish.className = "fish-cursor";
14	  fish.setAttribute("aria-hidden", "true");
15	  fish.innerHTML = `
16	    <svg viewBox="0 0 50 36" width="50" height="36">
17	      <g class="fish-tail">
18	        <path d="M14 18 L2 7 Q5 18 2 29 Z" fill="#1fb8a0" />
19	      </g>
20	      <path d="M22 9 Q27 1 33 8 Z" fill="#1fb8a0" />
21	      <ellipse cx="29" cy="18" rx="17" ry="11" fill="#2de0c4" />
22	      <path d="M17 21 Q29 31 43 22 Q30 26 17 21 Z" fill="#b8fff1" opacity="0.8" />
23	      <path d="M26 20 Q30 25 32 20" fill="#1fb8a0" />
24	      <circle cx="37" cy="15" r="4" fill="#fff" />
25	      <circle cx="38" cy="15.5" r="2.4" fill="#0a1a33" />
26	      <circle cx="38.8" cy="14.5" r="0.9" fill="#fff" />
27	      <ellipse cx="36" cy="21" rx="2.2" ry="1.3" fill="#ff8fa3" opacity="0.7" />
28	      <path d="M43 20 Q45 21 44 22" stroke="#0a1a33" stroke-width="1" fill="none" stroke-linecap="round" />
29	    </svg>`;
30	  document.body.appendChild(fish);
31	
32	  let x = -100, y = -100;     // pointer position
33	  let lastX = x, lastY = y;
34	  let facing = 1;             // 1 = right, -1 = left
35	  let tilt = 0;
36	  let speed = 0;
37	  let lastBubble = 0;
38	  let active = false;
39	
40	  const onHome = () => !home.classList.contains("hidden");
41	
42	  const bubble = (bx, by, size, burst) => {
43	    const b = document.createElement("span");
44	    b.className = "fish-bubble" + (burst ? " burst" : "");
45	    b.style.left = bx + "px";
46	    b.style.top = by + "px";
47	    b.style.width = b.style.height = size + "px";
48	    b.style.setProperty("--drift", (Math.random() * 30 - 15).toFixed(1) + "px");
49	    b.addEventListener("animationend", () => b.remove());
50	    document.body.appendChild(b);
51	  };
52	
53	  window.addEventListener("mousemove", (e) => { x = e.clientX; y = e.clientY; });
54	  document.addEventListener("mouseleave", () => { fish.style.opacity = "0"; });
55	  document.addEventListener("mouseenter", () => { if (active) fish.style.opacity = "1"; });
56	
57	  // Clicking makes the fish gulp and puff out a ring of bubbles.
58	  window.addEventListener("mousedown", () => {
59	    if (!active) return;
60	    fish.classList.remove("gulp");
61	    void fish.offsetWidth; // restart the animation
62	    fish.classList.add("gulp");
63	    for (let i = 0; i < 6; i++) bubble(x + facing * 4, y, 5 + Math.random() * 7, true);
64	  });
65	
66	  const frame = (t) => {
67	    const nowActive = onHome();
68	    if (nowActive !== active) {
69	      active = nowActive;
70	      document.body.classList.toggle("fish-mode", active);
71	      fish.style.opacity = active ? "1" : "0";
72	    }
73	
74	    if (active) {
75	      const dx = x - lastX, dy = y - lastY;
76	      speed = speed * 0.85 + Math.hypot(dx, dy) * 0.15;
77	      if (Math.abs(dx) > 1.5) facing = dx > 0 ? 1 : -1;
78	      // Nose tips up or down with vertical motion.
79	      const targetTilt = Math.max(-30, Math.min(30, dy * 2.5)) * facing;
80	      tilt += (targetTilt - tilt) * 0.2;
81	
82	      fish.style.transform =
83	        `translate(${x - 46}px, ${y - 18}px) scaleX(${facing}) rotate(${tilt.toFixed(1)}deg)`;
84	      // Tail wags faster the faster the fish swims.
85	      fish.style.setProperty("--wag", Math.max(0.12, 0.6 - speed * 0.03).toFixed(2) + "s");
86	
87	      if (speed > 3 && t - lastBubble > 90) {
88	        lastBubble = t;
89	        bubble(x - facing * 40, y + (Math.random() * 8 - 4), 4 + Math.random() * 6, false);
90	      }
91	    }
92	
93	    lastX = x; lastY = y;
94	    requestAnimationFrame(frame);
95	  };
96	  requestAnimationFrame(frame);
97	})();
