const http = require("http"), fs = require("fs"), path = require("path");
const root = process.argv[2];
const types = { ".html": "text/html", ".js": "text/javascript", ".css": "text/css", ".svg": "image/svg+xml" };
http.createServer((req, res) => {
  let p = decodeURIComponent(req.url.split("?")[0]);
  if (p === "/") p = "/index.html";
  const f = path.join(root, path.normalize(p));
  if (!f.startsWith(root)) { res.writeHead(403); return res.end(); }
  fs.readFile(f, (err, data) => {
    if (err) { res.writeHead(404); return res.end("not found"); }
    res.writeHead(200, { "Content-Type": types[path.extname(f)] || "application/octet-stream", "Cache-Control": "no-store" });
    res.end(data);
  });
}).listen(5174, () => console.log("ready on 5174"));

// Drives headless Chrome over CDP: plays the game at a given viewport,
// reports page overflow, peek/button overlap, hook alignment, and saves screenshots.
import { spawn } from "node:child_process";
import fs from "node:fs";
import path from "node:path";

const [W, H, tag, modeArg] = [Number(process.argv[2]), Number(process.argv[3]), process.argv[4], process.argv[5] || "easy"];
const out = path.dirname(new URL(import.meta.url).pathname.replace(/^\/(\w:)/, "$1"));
const port = 9300 + Math.floor(Math.random() * 500);
const prof = path.join(out, `prof-${tag}`);
const chrome = spawn("C:/Program Files/Google/Chrome/Application/chrome.exe",
  ["--headless=new", `--remote-debugging-port=${port}`, `--user-data-dir=${prof}`, "--no-first-run", `--window-size=${W},${H}`, "about:blank"]);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

let targets;
for (let i = 0; i < 50; i++) {
  try { targets = await (await fetch(`http://127.0.0.1:${port}/json`)).json(); break; } catch { await sleep(200); }
}
const page = targets.find((t) => t.type === "page");
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((r) => ws.addEventListener("open", r));
let id = 0; const pending = new Map();
ws.addEventListener("message", (e) => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } });
const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
const ev = async (expr) => { const r = await send("Runtime.evaluate", { expression: expr, awaitPromise: true, returnByValue: true }); if (r.result.exceptionDetails) throw new Error(JSON.stringify(r.result.exceptionDetails)); return r.result.result.value; };
const shot = async (name) => { const r = await send("Page.captureScreenshot", { format: "png" }); fs.writeFileSync(path.join(out, `${tag}-${name}.png`), Buffer.from(r.result.data, "base64")); };

await send("Emulation.setDeviceMetricsOverride", { width: W, height: H, deviceScaleFactor: 1, mobile: W < 500 });
await send("Page.enable"); await send("Runtime.enable");
const errors = [];
ws.addEventListener("message", (e) => { const m = JSON.parse(e.data); if (m.method === "Runtime.exceptionThrown") errors.push(m.params.exceptionDetails.exception?.description); });
await send("Page.navigate", { url: "http://localhost:5174/" });
await sleep(1500);

const overflow = () => ev(`({ doc: document.documentElement.scrollHeight, view: innerHeight, overX: document.documentElement.scrollWidth > innerWidth, screen: document.body.dataset.screen, board: getComputedStyle(document.querySelector('.leaderboard')).display })`);
console.log("home", JSON.stringify(await overflow()));
await shot("0-home");

await ev(`document.getElementById('username').value='Tester'; document.querySelector('.mode[data-mode="${modeArg}"]').click()`);
await sleep(300);
console.log("mission", JSON.stringify(await overflow()));
await shot("1-mission");
await ev(`document.getElementById('btn-start').click()`);

const answers = ["Legit", "Phish", "Legit", "Phish", "Legit"];
for (let r = 0; r < 5; r++) {
  await sleep(600);
  const before = await overflow();
  // Link popup check: hover the link chip and compare against the answer buttons
  const peek = await ev(`(() => {
    const chip = document.querySelector('.link-chip'); if (!chip) return 'no link';
    chip.dispatchEvent(new MouseEvent('mouseover', { bubbles: true }));
    const p = document.getElementById('link-peek').getBoundingClientRect();
    const hit = [...document.querySelectorAll('.answer')].some((b) => { const q = b.getBoundingClientRect(); return !(p.right <= q.left || p.left >= q.right || p.bottom <= q.top || p.top >= q.bottom); });
    return { peek: [p.left, p.top, p.right, p.bottom].map(Math.round), coversButtons: hit };
  })()`);
  if (r === 0) await shot(`2-round${r + 1}-peek`);
  await ev(`(() => { const c = document.querySelector('.link-chip'); c && c.dispatchEvent(new MouseEvent('mouseout', { bubbles: true, relatedTarget: document.body })); })()`);

  // Click the answer, then sample where the hook lands vs. the message card
  await ev(`window.__rig = null; new MutationObserver((ms) => ms.forEach((m) => m.addedNodes.forEach((n) => { if (n.classList && n.classList.contains('hook-rig')) { const card = document.getElementById('message').firstElementChild.getBoundingClientRect(); window.__rig = { rigX: parseFloat(n.style.left) - scrollX, cardMid: card.left + card.width/2, drop: parseFloat(n.style.getPropertyValue('--drop')), cardTop: card.top }; } }))).observe(document.body, { childList: true }); document.getElementById('btn-${answers[r] === "Phish" ? "phish" : "legit"}').click()`);
  await sleep(450);
  if (r < 2) await shot(`3-round${r + 1}-mid-anim`);
  await sleep(1600);
  const after = await overflow();
  const info = await ev(`({ reaction: document.getElementById('reaction').className, rig: window.__rig, next: (() => { const b = document.getElementById('btn-next').getBoundingClientRect(); return { top: Math.round(b.top), bottom: Math.round(b.bottom) }; })(), progress: document.getElementById('progress').textContent, channel: document.querySelector('#message .sms') ? 'sms' : 'email' })`);
  console.log(`round ${r + 1}`, JSON.stringify({ before, after, peek, ...info }));
  await shot(`4-round${r + 1}-answered`);
  await ev(`document.getElementById('btn-next').click()`);
}
await sleep(1800);
console.log("end", JSON.stringify(await overflow()));
await shot("5-end");

// Contacts panel on the play screen
console.log("errors", JSON.stringify(errors));
ws.close(); chrome.kill();
await sleep(500);
try { fs.rmSync(prof, { recursive: true, force: true }); } catch {}
process.exit(0);

